func (TalksRow) TableName() string { return "catalog_talks" }
func writeTalks(tx *gorm.DB, values assets.Talks) error {
	var rows []TalksRow
	{
		key, value := 1, values
		row := TalksRow{TalksKey: key}
		row.ValueByIDPresent = value.ByID != nil
		row.ValueByIndexPresent = value.ByIndex != nil
		row.ValueByOffsetPresent = value.ByOffset != nil
		rows = append(rows, row)
	}
	if len(rows) > 0 {
		if err := tx.CreateInBatches(&rows, catalogWriteBatch).Error; err != nil {
			return err
		}
	}
	{
		key, value := 1, values
		if err := writeTalksByID(tx, value.ByID, key); err != nil {
			return err
		}
		if err := writeTalksByIndex(tx, value.ByIndex, key); err != nil {
			return err
		}
		if err := writeTalksByOffset(tx, value.ByOffset, key); err != nil {
			return err
		}
	}
	return nil
}
func readTalks(tx *gorm.DB) (assets.Talks, error) {
	var result assets.Talks
	var rows []TalksRow
	query := tx
	if err := query.Order("talks_key").Find(&rows).Error; err != nil {
		return result, err
	}
	if len(rows) != 1 {
		return result, fmt.Errorf("missing singleton catalog row")
	}
	for _, row := range rows {
		var value assets.Talks
		if row.ValueByIDPresent {
			var err error
			value.ByID, err = readTalksByID(tx, row.TalksKey)
			if err != nil {
				return result, err
			}
		}
		if row.ValueByIndexPresent {
			var err error
			value.ByIndex, err = readTalksByIndex(tx, row.TalksKey)
			if err != nil {
				return result, err
			}
		}
		if row.ValueByOffsetPresent {
			var err error
			value.ByOffset, err = readTalksByOffset(tx, row.TalksKey)
			if err != nil {
				return result, err
			}
		}
		result = value
	}
	return result, nil
}

